	/**  Viewport height in CSS pixels. */
	height: number,
	/**  Device pixel ratio. */
	dpr: number | null,
	/**  Mobile layout (viewport meta honored, overlay scrollbars). */
	mobile: boolean,
	/**  Emit touch events for mouse input. */
	touch: boolean,
