/**  One step in a request's life. The chrome merges these by `request_id`. */
export type NetworkEvent =
/**  A request left the browser. */
{ type: "sent"; data: {
	/**  Tab that issued it. */
	tab_id: TabId,
	/**  CDP request id, unique per session. */
	request_id: string,
	/**  Full URL. */
	url: string,
	/**  HTTP method. */
	method: string,
	/**  `Document`, `Script`, `XHR`, `Fetch`, `Image`, ... */
	resource_type: string,
	/**  Request headers as sent by the renderer. */
	headers: { [key in string]: string },
	/**  Request body when present and small. */
	post_data: string | null,
	/**  Seconds since an arbitrary monotonic origin. */
	timestamp: number | null,
	/**  Seconds since the epoch, for exports. */
	wall_time: number | null,
} } |
/**  Headers arrived. */
{ type: "response"; data: {
	/**  Tab. */
	tab_id: TabId,
	/**  Request id. */
	request_id: string,
	/**  HTTP status. */
	status: number,
	/**  Content type without parameters. */
	mime_type: string,
	/**  Whether it was served from cache. */
	from_cache: boolean,
	/**  Response headers. */
	headers: { [key in string]: string },
	/**  Seconds. */
	timestamp: number | null,
} } |
/**  Body fully received. */
{ type: "finished"; data: {
	/**  Tab. */
	tab_id: TabId,
	/**  Request id. */
	request_id: string,
	/**  Bytes on the wire. */
	encoded_length: number | null,
	/**  Seconds. */
	timestamp: number | null,
} } |
/**  A WebSocket handshake started; shown as a request row. */
{ type: "socket"; data: {
	/**  Tab. */
	tab_id: TabId,
	/**  Request id. */
	request_id: string,
	/**  Socket URL. */
	url: string,
	/**  Seconds. */
	timestamp: number | null,
} } |
/**  A WebSocket frame or a server-sent event. */
{ type: "frame"; data: {
	/**  Tab. */
	tab_id: TabId,
	/**  Request id of the socket or event stream. */
	request_id: string,
	/**  `sent` or `received`. */
	direction: string,
	/**  Text payload, truncated; binary frames are summarised. */
	payload: string,
	/**  Seconds. */
	timestamp: number | null,
} } |
/**  Request failed or was blocked. */
{ type: "failed"; data: {
	/**  Tab. */
	tab_id: TabId,
	/**  Request id. */
	request_id: string,
	/**  Chromium error text, e.g. `net::ERR_FAILED`. */
	error: string,
	/**  Seconds. */
	timestamp: number | null,
} };

