/**  What the picker found. */
export type Pick = {
	/**  Tab it came from. */
	tab_id: TabId,
	/**  Page URL at the time. */
	page_url: string,
	/**  Page title at the time. */
	page_title: string | null,
	/**  Lowercased tag name. */
	tag_name: string,
	/**  ARIA role, when it has one. */
	role: string,
	/**  Accessible name. */
	name: string,
	/**  CSS path. */
	selector: string | null,
	/**  Locator that addresses it, for handing to an agent. */
	locator: string | null,
	/**  First 500 characters of `outerHTML`. */
	html_preview: string,
	/**  A readable dump of the properties worth knowing. */
	styles: string,
	/**  React component, when the page is a development React build. */
	component_name: string | null,
	/**  Where that component is defined, as the bundle reports it. */
	source: SourceFrame | null,
	/**  The owner chain above it. */
	stack: SourceFrame[],
	/**  Component names from the element outwards. */
	owners: string[],
	/**  Where `source` maps to once source maps are applied. */
	source_resolved: Original | null,
	/**  RFC 3339 pick time. */
	picked_at: string,
};

/**
 *  Every preference, with the defaults a fresh profile starts on. Stored blobs
 *  from older builds are merged with [`Prefs::default`] when they are loaded.
 */
export type Prefs = {
	/**  Chrome theme: `system` | `dark` | `light`. Applied by the chrome. */
	theme: string,
	/**  Accent color as a CSS hex string. Applied by the chrome. */
	accent: string,
	/**
	 *  Force pages to see the chrome's color scheme. Ignored while the theme
	 *  follows the system, since the host cannot read the OS setting.
	 */
	tell_pages_theme: boolean,
	/**
	 *  What opens at launch: the `home` page, `restore` for the tab the last
	 *  session ended on, or `none` for the welcome screen. A `home` start with
	 *  no homepage set is the welcome screen.
	 */
	startup: string,
	/**  Home page URL; empty means the welcome screen. */
	homepage: string,
	/**  Search engine key, or `custom` to use [`Prefs::search_template`]. */
	search_engine: string,
	/**  Custom search URL with a `{query}` placeholder. */
	search_template: string,
	/**  Zoom factor new tabs open at. */
	default_zoom: number | null,
	/**  Send `DNT: 1` and `Sec-GPC: 1` with every request. */
	do_not_track: boolean,
	/**  Block the built-in list of tracker and ad hosts. */
	block_trackers: boolean,
	/**  Extra hosts or URL globs to block, one per entry. */
	blocked_patterns: string[],
	/**  Apply narrow `YouTube` privacy interventions when `DivePrivacy` is active. */
	youtube_protection?: boolean,
	/**  Exact document hosts where `DivePrivacy` is disabled. */
	privacy_exceptions?: string[],
	/**  Run page scripts. Off makes every tab script-free. */
	javascript: boolean,
	/**  Days of history to keep; `0` keeps it forever. */
	history_days: number,
	/**  Directory downloads are written to; empty means `~/Downloads`. */
	download_dir: string,
	/**  Open `DevTools` for every new tab. */
	devtools_on_open: boolean,
	/**  Workspace rail shows names and tab counts rather than marks alone. */
	rail_expanded: boolean,
	/**  Provider the agent talks to; a `dive_agent::Provider` id. */
	agent_provider: string,
	/**  Model the agent talks to, in the provider's naming. */
	agent_model: string,
	/**  Reasoning depth: `default` | `low` | `medium` | `high` | `max`. */
	agent_reasoning: string,
	/**  Most tool calls one message may make before the run is stopped. */
	agent_max_steps: number,
	/**  Let the agent act on a page without asking first. */
	agent_auto_approve: boolean,
	/**  Send the current tab's title, URL, console and text with each message. */
	agent_include_page: boolean,
	/**  Base URL of the custom OpenAI-compatible endpoint. */
	agent_custom_base_url: string,
	/**  Preferred code editor for Jump-to-Source: `vscode` | `cursor` | `zed`. */
	preferred_editor?: string,
	/**  Chrome palette template; one of [`APPEARANCE_PRESETS`] or `custom`. */
	appearance_preset?: string,
	/**  Custom template seed: the ground (window) colour as CSS hex. */
	custom_ground?: string,
	/**  Custom template seed: the text colour as CSS hex. */
	custom_ink?: string,
	/**  Custom template seed: the highlight colour as CSS hex. */
	custom_highlight?: string,
	/**  Chrome typeface: `geist` | `system` | `mono` | `serif`. */
	ui_font?: string,
	/**  Chrome size multiplier, 0.8 to 1.3; everything in the chrome scales. */
	ui_scale?: number | null,
	/**  Row heights and gaps: `compact` | `comfortable` | `relaxed`. */
	density?: string,
	/**  Corner rounding of chrome controls: `sharp` | `soft` | `round`. */
	corner_radius?: string,
	/**  Tab strip look: `pill` | `flat`. */
	tab_style?: string,
	/**  Chrome motion: follow the `system`, `reduce`, or always `full`. */
	motion?: string,
	/**  Welcome screen backdrop: `orbs` | `plain` | `gradient`. */
	welcome_background?: string,
	/**
	 *  Offer a hover control that fills the tab with a video, without
	 *  leaving the window.
	 */
	video_fill_tab?: boolean,
};

/**  A named device, as the chrome's simulator and `page_resize` both see it. */
export type Preset = {
	/**  Stable id, for example `iphone-15`. */
	id: string,
	/**  Display name. */
	name: string,
	/**  Catalog group, for example `apple-phone`. */
	group: string,
	/**  Which frame it is drawn in. */
	frame: Frame,
	/**  Which browser's bars are drawn: `safari`, `chrome` or `none`. */
	browser: string,
	/**  Safe-area insets in portrait with `viewport-fit=cover`. */
	safe_area: Insets,
	/**  The device itself. */
	device: Device,
};

/**  Categories reported for network requests blocked by `DivePrivacy`. */
export type PrivacyCategory =
/**  Advertising delivery and auction infrastructure. */
"ads" |
/**  Analytics, telemetry, fingerprinting, and cryptomining infrastructure. */
"tracker";

/**  A privacy action the chrome may summarize without exposing browsing URLs. */
export type PrivacyEvent =
/**  A network request was cancelled by `DivePrivacy`. */
{ type: "blocked"; data: {
	/**  Tab whose request was cancelled. */
	tab_id: TabId,
	/**  Which bundled matcher blocked it. */
	category: PrivacyCategory,
} } |
/**  A narrow `YouTube` privacy intervention was observed in a document. */
{ type: "youtube"; data: {
	/**  Tab whose document received the intervention. */
	tab_id: TabId,
	/**  Number of reported interventions. */
	count: number,
} };

/**  Public metadata about the bundled `DivePrivacy` assets. */
export type PrivacyInfo = {
	/**  Bundled ruleset version. */
	version: string,
	/**  Number of advertising network rules. */
	ad_rules: number,
	/**  Number of tracking network rules. */
	tracker_rules: number,
	/**  Number of hosts with cosmetic rules. */
	cosmetic_hosts: number,
};

/**
 *  A person using the browser: a name and a face, a container of its own
 *  (cookies and logins), and the workspaces that belong to it. Switching
 *  profile switches which workspaces the rail shows.
 */
export type Profile = {
	/**  Stable id. */
	id: ProfileId,
	/**  Display name. */
	name: string,
	/**  Accent color as a CSS hex string. */
	color: string,
	/**  Avatar seed the chrome draws a face from. */
	avatar: string,
	/**  A line under the name: a role, an email, whatever tells it apart. */
	note: string,
	/**  Container this profile's workspaces browse in unless one asks for its own. */
	container_id: ContainerId,
	/**  Order in the switcher; lower first. */
	position: number,
	/**  Creation timestamp. */
	created_at: string,
};

/**  What a profile is made of, from the profile dialog. */
export type ProfileDraft = {
	name: string,
	color: string,
	/**  Avatar seed. */
	avatar: string,
	note: string,
};

/**  Identifies a [`Profile`]. */
export type ProfileId = string;

/**  A provider in the catalog. */
export type Provider =
/**  Anthropic, first party. */
"anthropic" |
/**  `OpenRouter`: one key, every model. */
"openrouter" |
/**  `OpenAI`. */
"openai" |
/**  Google Gemini through its OpenAI-compatible endpoint. */
"google" |
/**  xAI Grok. */
"xai" |
/**  Groq. */
"groq" |
/**  Mistral. */
"mistral" |
/**  `DeepSeek`. */
"deepseek" |
/**  Together AI. */
"together" |
/**  Fireworks AI. */
"fireworks" |
/**  Cerebras. */
"cerebras" |
/**  Ollama, running locally. */
"ollama" |
/**  LM Studio, running locally. */
"lmstudio" |
/**  Any other OpenAI-compatible server, by base URL. */
"custom";

/**  Everything the chrome and the client need to know about one provider. */
export type ProviderInfo = {
	/**  Stable id, also the preferences value. */
	id: Provider,
	/**  Display name. */
	name: string,
	/**  Protocol. */
	wire: Wire,
	/**  Base URL; the client appends the endpoint path. */
	base_url: string,
	/**  Where to create an API key. */
	key_url: string,
	/**  What a key from this provider starts with, for the placeholder. */
	key_hint: string,
	/**  Whether requests need a key at all. Local servers do not. */
	needs_key: boolean,
	/**  Whether `GET /models` answers with something worth showing. */
	lists_models: boolean,
	/**  Model chosen when the provider is first selected. */
	default_model: string,
	/**  One line for the picker. */
	note: string,
};

/**  What the person asked for in the recording dialog. */
export type RecordOptions = {
	/**  `mp4` or `gif`. */
	format: string,
	/**  Frames per second of the encoded video. */
	fps: number,
	/**  Widest the captured frames may be, in CSS pixels. */
	max_width: number,
	/**  Microphone to record alongside, by capture-device id; `None` for none. */
	microphone: string | null,
	/**
	 *  `page` (the tab's own paint, through `DevTools`) or `window` (Dive's
	 *  window as it appears on screen, pointer included, through native
	 *  screen capture).
	 */
	source?: string,
};

/**  One recorded interaction. */
export type RecordedStep = {
	/**  `click` | `type` | `navigate`. */
	kind: string,
	/**  ARIA role of the target. */
	role: string,
	/**  Accessible name of the target. */
	name: string,
	/**  Typed text for `type`; URL for `navigate`. */
	value: string,
	/**  Milliseconds since the epoch. */
	at: number | null,
	/**  The value was a secret (password, card, one-time code) and was not recorded. */
	masked?: boolean,
};

/**  Emitted to the chrome for each recorded step. */
export type RecorderEvent = {
	/**  Tab being recorded. */
	tab_id: TabId,
	/**  The step. */
	step: RecordedStep,
};

/**  What this machine can do, so the dialog offers only what will work. */
export type RecordingCapabilities = {
	/**  ffmpeg was found; without it only GIF is possible. */
	ffmpeg: boolean,
	/**  Microphones, when ffmpeg can list them. */
	microphones: Microphone[],
	/**  Length cap of a video, seconds. */
	video_max_seconds: number,
	/**  Length cap of a GIF, seconds. */
	gif_max_seconds: number,
};

/**  Something the chrome should react to while a recording runs. */
export type RecordingEvent = {
	/**  The tab being recorded. */
	tab: TabId,
	/**  `limit` when the length cap was reached and no more frames are kept. */
	kind: string,
};

/**  One finished recording in the captures directory. */
export type RecordingInfo = {
	path: string,
	name: string,
	/**  `mp4` or `gif`. */
	format: string,
	/**  Size on disk. A float because the bindings cannot carry a u64. */
	bytes: number | null,
	/**  Last modified, milliseconds since the epoch. */
	modified_ms: number | null,
	/**  Whether a playable companion exists (so it can open in `DiveScreen`). */
	editable: boolean,
	/**  Whether a project file exists beside it. */
	has_project: boolean,
};

/**  The finished file. */
export type RecordingResult = {
	/**  Where it was written. */
	path: string,
	/**  Length in seconds, pauses excluded. */
	duration_secs: number | null,
	/**  Size on disk. A float because the bindings cannot carry a u64. */
	bytes: number | null,
	/**  Pixel size of the encoded picture. */
	width: number,
	/**  Pixel size of the encoded picture. */
	height: number,
	/**  `mp4` or `gif`. */
	format: string,
	/**  Frames captured. */
	frames: number,
	/**  Whether a microphone track is in the file. */
	has_audio: boolean,
	/**
	 *  Pointer positions and clicks over the recording, for the editor's
	 *  cursor and zoom effects. A JSON sidecar; `None` when nothing was
	 *  tracked (window captures carry the pointer in the picture already).
	 */
	events: string | null,
	/**
	 *  A small `WebM` the chrome can play, beside the MP4: the embedded
	 *  Chromium ships without H.264, so the file itself cannot be previewed.
	 *  `None` for a GIF, which previews as is.
	 */
	preview: string | null,
};

/**  What to send. Starts as the captured request; the user may edit it. */
export type ReplayRequest = {
	/**  HTTP method. */
	method: string,
	/**  Absolute URL. */
	url: string,
	/**  Headers to send (hop-by-hop ones are dropped). */
	headers: { [key in string]: string },
	/**  Body text, if any. */
	body: string | null,
	/**  Attach the tab's cookies for this URL. */
	with_cookies: boolean,
	/**  Host of the captured request; cookies are only ever sent there. */
	captured_host: string,
};

/**  What came back. */
export type ReplayResponse = {
	/**  HTTP status. */
	status: number,
	/**  Response headers. */
	headers: { [key in string]: string },
	/**  Body text, truncated to 256 kB; binary bodies are described. */
	body: string,
	/**  Round-trip time. */
	elapsed_ms: number,
};

/**  One rule; the first enabled match wins. */
export type Rule = {
	id: string,
	/**  URL glob; `*` matches any run of characters. Matched case-insensitively. */
	pattern: string,
	enabled: boolean,
	action: RuleAction,
};

/**  What happens to a matching request. */
export type RuleAction =
/**  Fail the request as blocked by the client. */
{ kind: "block" } |
/**  Answer without hitting the network. */
{ kind: "mock"; status: number; content_type: string; body: string } |
/**  Add or replace one request header. */
{ kind: "header"; name: string; value: string };

export type Scope = {
	profile_id: ProfileId,
	container_id: ContainerId,
};

/**  Per-message switches from the chrome. */
export type SendOptions = {
	/**  Attach the current tab's title, URL, console, failed requests and text. */
	include_page: boolean,
	/**  Run actions without asking, for this message only. */
	auto_approve: boolean,
};

/**  LAN address plus a QR code for it. */
export type ShareInfo = {
	/**  The URL rewritten to this machine's LAN IP. */
	lan_url: string,
	/**  SVG markup of a QR code for `lan_url`. */
	qr_svg: string,
};

/**  A remembered decision, for the settings UI. */
export type SitePermission = {
	/**  Scheme and host the decision applies to. */
	origin: string,
	/**
	 *  `camera`, `microphone`, `geolocation`, `notifications`,
	 *  `clipboard_read` or `display_capture`.
	 */
	kind: string,
	/**  The decision. */
	decision: Decision,
	scope: Scope,
};

/**  Everything the chrome needs to render on boot. */
export type Snapshot = {
	/**  All workspaces in rail order. */
	workspaces: Workspace[],
	/**  Workspace shown in the chrome. */
	active_workspace: WorkspaceId | null,
	/**  Tabs of the active workspace plus essentials. */
	tabs: Tab[],
	/**  Focused tab, if any. */
	active_tab: TabId | null,
	/**  Tabs shown in their own windows. */
	detached: TabId[],
	/**  Every profile, in switcher order. */
	profiles: Profile[],
	/**  The profile the active workspace belongs to. */
	active_profile: ProfileId | null,
};

/**  One frame of a component's source location. */
export type SourceFrame = {
	/**  Component or function name, when known. */
	function_name: string | null,
	/**  File as the bundle reports it. */
	file_name: string,
	/**  1-based line. */
	line_number: number | null,
	/**  1-based column. */
	column_number: number | null,
};

/**  Emitted whenever core state changes; carries the change itself. */
export type StateChanged = CoreEvent;

/**  Everything the Storage panel shows. */
export type StorageSnapshot = {
	/**  Cookies visible to the page's URL. */
	cookies: Cookie[],
	/**  `localStorage` entries as `[key, value]`. */
	local: ([string, string])[],
	/**  `sessionStorage` entries as `[key, value]`. */
	session: ([string, string])[],
};

/**  A style the person changed on the picked element. */
export type StyleChange = StyleChange_Serialize | StyleChange_Deserialize;

/**  A style the person changed on the picked element. */
export type StyleChange_Deserialize = {
	/**  CSS property. */
	property: string,
	/**  What it is now. */
	value: string,
	/**  CSS path of the element it applies to. */
	selector: string | null,
	/**  Locator for the element, which survives a re-render. */
	locator: string | null,
} & {
	/**  What it was before, computed or inline. */
	previous_value: string,
} | {
	/**  What it was before, computed or inline. */
	previousValue: string,
} & {
	/**  Component that rendered it, when known. */
	component_name: string | null,
} | {
	/**  Component that rendered it, when known. */
	componentName: string | null,
};

/**  A style the person changed on the picked element. */
export type StyleChange_Serialize = {
	/**  CSS property. */
	property: string,
	/**  What it was before, computed or inline. */
	previous_value: string,
	/**  What it is now. */
	value: string,
	/**  CSS path of the element it applies to. */
	selector: string | null,
	/**  Locator for the element, which survives a re-render. */
	locator: string | null,
	/**  Component that rendered it, when known. */
	component_name: string | null,
};

/**  A caption line for the overlay. */
export type SubtitleCue = {
	/**  Tab the caption belongs to. */
	tab_id: TabId,
	/**  The transcribed (or translated) text. */
	text: string,
	/**  Language the model detected or was told to use. */
	language: string,
	/**  True once the line is stable and will not be revised. */
	is_final: boolean,
};

/**  A downloadable whisper model. */
export type SubtitleModel = {
	/**  Stable id used in commands and the file name. */
	id: string,
	/**  Human label for the picker. */
	label: string,
	/**  A one-line note on the speed/accuracy trade. */
	detail: string,
	/**  Approximate download size in megabytes. */
	size_mb: number,
	/**  Whether the file is already on disk. */
	downloaded: boolean,
};

/**  Progress of a model download. */
export type SubtitleModelProgress = {
	/**  Model id. */
	id: string,
	/**  Bytes received so far. */
	received: number | null,
	/**  Total bytes, when the server reported a length. */
	total: number | null,
	/**  Set when the file is fully written and verified. */
	done: boolean,
	/**  A human message when the download failed. */
	error: string | null,
};

/**  Whether subtitles are running on a tab, with any error. */
export type SubtitleState = {
	/**  The tab. */
	tab_id: TabId,
	/**  Running or stopped. */
	active: boolean,
	/**  A human message when it could not start or stay running. */
	error: string | null,
};

/**  A browsing tab. */
export type Tab = {
	/**  Stable id. */
	id: TabId,
	/**  Owning workspace; `None` for essentials. */
	workspace_id: WorkspaceId | null,
	/**  Which strip it lives in. */
	tier: TabTier,
	/**  Current URL. */
	url: string,
	/**  Page title, empty until loaded. */
	title: string,
	/**
	 *  Site icon as a `data:` URL, resolved from the page once it loads.
	 *  `None` until then, and cleared whenever the tab leaves its origin.
	 */
	favicon: string | null,
	/**  Order within its tier; lower first. */
	position: number,
	/**  Renderer state. */
	state: TabState,
	/**  Last time the tab was focused. */
	last_active_at: string,
};

/**  Emitted when a tab's renderer dies, whether or not it is being recovered. */
export type TabCrashed = {
	/**  The tab that lost its renderer. */
	tab_id: TabId,
	/**  Which attempt this is, within the current window. */
	attempt: number,
	/**  Whether Dive is reloading it. */
	recovering: boolean,
};

export type TabHistoryChanged = {
	tab_id: TabId,
};

/**  Identifies a [`Tab`]. */
export type TabId = string;

/**  A change in a tab's loading state. */
export type TabLoad = {
	/**  The tab. */
	tab_id: TabId,
	/**  What happened. */
	phase: LoadPhase,
	/**  The URL involved, when the engine reported one. */
	url: string | null,
	/**  Chromium's error text for `Failed`, e.g. `net::ERR_NAME_NOT_RESOLVED`. */
	error: string | null,
};

/**  Lifecycle state of a tab's renderer. */
export type TabState =
/**  Renderer alive and painting. */
"active" |
/**  Renderer alive but throttled. */
"sleeping" |
/**  Renderer torn down; only metadata kept. */
"discarded";

/**  Which strip a tab lives in. */
export type TabTier =
/**  Global, shown in every workspace. */
"essential" |
/**  Pinned to one workspace, never auto-archived. */
"pinned" |
/**  Ordinary tab, auto-archived after inactivity. */
"today";

/**  A tab moved into its own window, or back into the main one. */
export type TabWindowChanged = {
	/**  The tab. */
	tab: TabId,
	/**  Whether it now lives in its own window. */
	detached: boolean,
};

/**  A tool call, as shown in the thread. */
export type ToolStep = {
	/**  Call id. */
	id: string,
	/**  Tool name. */
	name: string,
	/**  Input as JSON text. */
	input: string,
	/**  Whether the tool changes the page. */
	action: boolean,
	/**  Playwright-style locator for the target, when the tool used a ref. */
	locator: string | null,
};

/**  An update the release channel offers. */
export type UpdateInfo = {
	/**  Version string of the update. */
	version: string,
	/**  Release notes, if the manifest carried any. */
	notes: string | null,
};

/**  Token accounting for one reply. */
export type Usage = {
	/**  Prompt tokens, including cached ones. */
	input_tokens: number,
	/**  Generated tokens, including reasoning. */
	output_tokens: number,
	/**  Prompt tokens served from cache. */
	cache_read_tokens: number,
	/**  Cost in USD when the provider reports it (`OpenRouter` does). */
	cost_usd: number | null,
};

/**  One failing rule. */
export type Violation = {
	/**  Rule id, e.g. `color-contrast`. */
	id: string,
	/**  `minor` | `moderate` | `serious` | `critical`. */
	impact: string,
	/**  Short description. */
	help: string,
	/**  Link to the rule documentation. */
	help_url: string,
	/**  CSS selectors of offending nodes (first 20). */
	targets: string[],
	/**  Total offending nodes. */
	count: number,
};

/**  Core metrics in milliseconds (CLS is unitless). */
export type Vitals = {
	/**  Time to first byte. */
	ttfb: number | null,
	/**  First contentful paint. */
	fcp: number | null,
	/**  Largest contentful paint. */
	lcp: number | null,
	/**  Cumulative layout shift. */
	cls: number | null,
	/**  Interaction to next paint (worst interaction so far). */
	inp: number | null,
	/**  `DOMContentLoaded`. */
	dcl: number | null,
	/**  Load event end. */
	load: number | null,
	/**  Transfer size of the document in bytes. */
	transfer_size: number | null,
	/**  Element description of the LCP candidate, when known. */
	lcp_element: string | null,
};

/**  Request and response shape a provider speaks. */
export type Wire =
/**  Anthropic Messages API: `POST /v1/messages`, content blocks, `tool_use`. */
"anthropic" |
/**  `OpenAI` chat completions: `POST /chat/completions`, `tool_calls`. */
"open_ai";

/**  A named set of tabs bound to one container. */
export type Workspace = {
	/**  Stable id. */
	id: WorkspaceId,
	/**  Display name. */
	name: string,
	/**  Accent color as a CSS hex string, e.g. `#0F6E75`. */
	color: string,
	/**  Icon identifier the UI resolves to a glyph, e.g. `layers`. */
	icon: string,
	/**  Container whose profile this workspace browses in. */
	container_id: ContainerId,
	/**  The profile this workspace belongs to. */
	profile_id: ProfileId,
	/**  Order in the rail; lower first. */
	position: number,
	/**  Creation timestamp. */
	created_at: string,
};

/**  Fields the chrome may set on a workspace. */
export type WorkspaceDraft = {
	/**  Display name. */
	name: string,
	/**  CSS color. */
	color: string,
	/**  Icon identifier the chrome resolves to a glyph. */
	icon: string,
};

/**  Identifies a [`Workspace`]. */
export type WorkspaceId = string;

/**  How many tabs a workspace holds, for the rail. */
export type WorkspaceTabs = {
	/**  The workspace. */
	workspace_id: WorkspaceId,
	/**  Open tabs in it, including discarded tabs. */
	tabs: number,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

